#include <iostream>
#include <string>
#include <vector>

struct Summary
{
    int words;
    int longest;
};

Summary summarise(const std::string& line)
{
    Summary out{ 0, 0 };

    std::size_t i{ 0 };
    while (i < line.size())
    {
        std::size_t j{ i };
        while (j < line.size() && line[j] != ' ') ++j;

        const int len{ static_cast<int>(j - i) };
        out.words += 1;
        if (len > out.longest) out.longest = len;

        i = j + 1;
    }

    return out;
}

int main()
{
    std::string line;
    std::getline(std::cin, line);

    const Summary s = summarise(line);
    std::cout << s.words << ' ' << s.longest << '\n';
    return 0;
}

